dtsPropsFor.Sparkline:
/** intraday close values; needs >= 2 points to draw */
  values: number[];
  /** true = up (var(--up)) stroke, false = down (var(--down)) */
  positive: boolean;
  /** viewBox width, default 400 */
  width?: number;
  /** pixel height, default 48 */
  height?: number;

dtsPropsFor.QuotePanel:
/** selected symbol's live quote; undefined shows an empty prompt */
  quote?: {
    symbol: string;
    price: number | null;
    change: number | null;
    change_pct: number | null;
    open: number | null;
    high: number | null;
    low: number | null;
    prev_close: number | null;
    spark: number[];
    updated_at: number;
    halted?: boolean;
    error?: string;
  };
  /** fundamentals for the same symbol; null shows "loading" */
  detail: {
    symbol: string;
    name?: string;
    week52_high?: number | null;
    week52_low?: number | null;
    volume?: number | null;
    pe?: number | null;
    market_cap?: number | null;
    industry?: string;
    exchange?: string;
  } | null;

dtsPropsFor.Watchlist:
watchlist: string[];
  /** symbol -> display name */
  names: Record<string, string>;
  /** symbol -> live quote */
  quotes: Record<string, {
    symbol: string;
    price: number | null;
    change_pct: number | null;
    halted?: boolean;
    error?: string;
  }>;
  selected: string | null;
  /** symbol currently used as the news filter, or null */
  newsFilter: string | null;
  onSelect: (sym: string) => void;
  onRemove: (sym: string) => void;
  onFilterNews: (sym: string) => void;

dtsPropsFor.NewsStream:
news: Array<{
    id: string;
    title: string;
    url: string;
    source: string;
    published_at: number;
    tickers: string[];
  }>;
  /** 'all' | 'domestic' | 'foreign' */
  scope: 'domestic' | 'foreign' | 'all';
  onScopeChange: (s: 'domestic' | 'foreign' | 'all') => void;
  /** ticker to filter headlines by, or null */
  filter: string | null;
  onClearFilter: () => void;

dtsPropsFor.IndicesPanel:
quotes: Array<{ symbol: string; price: number | null; change_pct: number | null; error?: string }>;
  /** symbol -> short label shown instead of the raw symbol */
  labels: Array<{ symbol: string; label: string }>;

dtsPropsFor.MarketsPanel:
quotes: Array<{ symbol: string; price: number | null; change_pct: number | null; error?: string }>;
  /** symbol -> short label shown instead of the raw symbol */
  labels: Array<{ symbol: string; label: string }>;

dtsPropsFor.HotPanel:
items: Array<{
    symbol: string;
    name: string;
    price: number | null;
    change_pct: number | null;
    market: 'KR' | 'US';
    sector: string | null;
    volume: number | null;
    news: Array<{ title: string; source: string; url: string }>;
  }>;
  /** first response arrived — distinguishes loading from an empty (market-closed) result */
  loaded: boolean;
  onSelect: (sym: string) => void;

dtsPropsFor.BriefPanel:
/** generated briefing text; null shows the disabled hint */
  text: string | null;
  loading: boolean;

dtsPropsFor.AlertTriggerButton:
/** alerts are on — shows a red dot */
  enabled: boolean;
  onClick: () => void;
